#include <flint/fmpq.h>
#include <flint/fmpq_poly.h>
#include <flint/nmod_mat.h>
#include <flint/nmod_poly.h>
#include <flint/ulong_extras.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cassert>
using namespace std;
struct Poly{fmpq_poly_struct p[1];Poly(){fmpq_poly_init(p);}Poly(const Poly&a):Poly(){fmpq_poly_set(p,a.p);}Poly(Poly&&a):Poly(){fmpq_poly_swap(p,a.p);}Poly&operator=(Poly a){fmpq_poly_swap(p,a.p);return *this;}~Poly(){fmpq_poly_clear(p);}};
void writeMatrix(const vector<vector<Poly>>&A,const string&path){ofstream o(path);assert(o.is_open());int n=A.size();o<<n<<' '<<n<<'\n';fmpq_t q;fmpq_init(q);long terms=0;for(auto&r:A){int nn=0;for(auto&a:r)nn+=!fmpq_poly_is_zero(a.p);o<<nn<<'\n';for(int j=0;j<n;j++)if(!fmpq_poly_is_zero(r[j].p)){o<<j<<'\n';int ct=0;for(int k=0;k<fmpq_poly_length(r[j].p);k++){fmpq_poly_get_coeff_fmpq(q,r[j].p,k);ct+=!fmpq_is_zero(q);}o<<ct;terms+=ct;for(int k=0;k<fmpq_poly_length(r[j].p);k++){fmpq_poly_get_coeff_fmpq(q,r[j].p,k);if(fmpq_is_zero(q))continue;char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<" 0 "<<k;flint_free(s);}o<<'\n';}}fmpq_clear(q);o.flush();assert(o.good());cerr<<"EXPORT "<<n<<" TERMS "<<terms<<'\n';}
int main(int argc,char**argv){assert(argc==5);ifstream in(argv[1]),meta(argv[2]);assert(in.is_open()&&meta.is_open());int n,m;in>>n>>m;assert(n==m);string word;int sz,upper;meta>>word>>sz>>word>>upper;assert(sz==n);meta>>sz;assert(sz==n);for(int i=0,x;i<n;i++)meta>>x;vector<int>rb(n),cb(n);meta>>word;assert(word=="ROW_BOUNDS");for(int&i:rb)meta>>i;meta>>word;assert(word=="COL_BOUNDS");for(int&i:cb)meta>>i;vector<vector<Poly>>A(n,vector<Poly>(n));fmpq_t q;fmpq_init(q);int maxdeg=0;for(int i=0;i<n;i++){int nn;in>>nn;for(int z=0;z<nn;z++){int j,ct;in>>j>>ct;for(int k=0;k<ct;k++){string s;int e,d;in>>s>>e>>d;assert(e==0&&d>=0);assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);int exponent=rb[i]+cb[j]-d;assert(exponent>=0);fmpq_poly_set_coeff_fmpq(A[i][j].p,exponent,q);maxdeg=max(maxdeg,exponent);}}}assert(in.good());string mode=argv[3];if(mode!="quad"){assert(!fmpq_set_str(q,mode.c_str(),10));fmpq_canonicalise(q);Poly linear;fmpq_poly_set_coeff_fmpq(linear.p,0,q);fmpq_poly_set_coeff_si(linear.p,1,1);for(auto&r:A)for(auto&a:r)fmpq_poly_compose(a.p,a.p,linear.p);writeMatrix(A,argv[4]);}else{ // f(e)=270e^2+321e-388; regular representation f(e)=delta.
 Poly h;fmpq_set_si(q,388,270);fmpq_poly_set_coeff_fmpq(h.p,0,q);fmpq_set_si(q,1,270);fmpq_poly_set_coeff_fmpq(h.p,1,q);fmpq_t c;fmpq_init(c);fmpq_set_si(c,321,270);vector<Poly>pu(maxdeg+1),pv(maxdeg+1);fmpq_poly_one(pu[0].p);for(int k=1;k<=maxdeg;k++){fmpq_poly_mul(pu[k].p,pv[k-1].p,h.p);Poly tmp;fmpq_poly_scalar_mul_fmpq(tmp.p,pv[k-1].p,c);fmpq_poly_sub(pv[k].p,pu[k-1].p,tmp.p);}vector<vector<Poly>>B(2*n,vector<Poly>(2*n));for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(!fmpq_poly_is_zero(A[i][j].p)){Poly u,v,tmp;for(int k=0;k<fmpq_poly_length(A[i][j].p);k++){fmpq_poly_get_coeff_fmpq(q,A[i][j].p,k);if(fmpq_is_zero(q))continue;fmpq_poly_scalar_mul_fmpq(tmp.p,pu[k].p,q);fmpq_poly_add(u.p,u.p,tmp.p);fmpq_poly_scalar_mul_fmpq(tmp.p,pv[k].p,q);fmpq_poly_add(v.p,v.p,tmp.p);}B[2*i][2*j]=u;B[2*i+1][2*j]=v;fmpq_poly_mul(B[2*i][2*j+1].p,v.p,h.p);fmpq_poly_scalar_mul_fmpq(tmp.p,v.p,c);fmpq_poly_sub(B[2*i+1][2*j+1].p,u.p,tmp.p);}nmod_mat_t NB,NA1,NA2;nmod_mat_init(NB,2*n,2*n,32003);nmod_mat_init(NA1,n,n,32003);nmod_mat_init(NA2,n,n,32003);nmod_poly_t np;nmod_poly_init(np,32003);ulong r2=(32003-287)*n_invmod(90,32003)%32003;for(int i=0;i<2*n;i++)for(int j=0;j<2*n;j++){fmpq_poly_get_nmod_poly(np,B[i][j].p);nmod_mat_entry(NB,i,j)=nmod_poly_evaluate_nmod(np,1334);}for(int i=0;i<n;i++)for(int j=0;j<n;j++){fmpq_poly_get_nmod_poly(np,A[i][j].p);nmod_mat_entry(NA1,i,j)=nmod_poly_evaluate_nmod(np,2);nmod_mat_entry(NA2,i,j)=nmod_poly_evaluate_nmod(np,r2);}ulong db=nmod_mat_det(NB),d1=nmod_mat_det(NA1),d2=nmod_mat_det(NA2);assert(db==d1*d2%32003);cerr<<"NORM_POINT_CHECK "<<db<<' '<<d1<<' '<<d2<<'\n';nmod_poly_clear(np);nmod_mat_clear(NB);nmod_mat_clear(NA1);nmod_mat_clear(NA2);writeMatrix(B,argv[4]);fmpq_clear(c);}fmpq_clear(q);}
